// Free writing per chapter: the learner writes a text, it is stored, and Claude marks it (admin loop).
export interface WritingTask {
  /** Situation and what to write, in simple German at the chapter level. Markdown bold allowed. */
  prompt: string;
  /** The same in American English. */
  promptEn: string;
  /** Three content points the text must cover (German). Also used for marking "Inhalt". */
  points: string[];
  pointsEn: string[];
  minWords: number;
  maxWords: number;
  /** 4-6 useful words or phrases as chips. */
  hints: string[];
  /** A model answer at the right level, within the word range. */
  sample: string;
}

